-- MIT. Prove only the owner-local ephemeral overlay contract, not package
-- expansion, composed-base fencing, migration ordering or automatic cleanup.
local registry = require("registry")
local logger = require("logger")
local OWNER = "bee.governance_overlay_probe:owner"
local SUBJECT = "bee.governance_overlay_probe:subject"
local function main()
    local base, base_error = registry.snapshot()
    assert(base, tostring(base_error))
    local original = base:version():id()
    local durable = base:changes()
    assert(durable)
    local staged = durable:create({id = SUBJECT, kind = "registry.entry", data = {value = "not-authorized"}})
    if staged then
        local published = durable:apply()
        assert(not published, "overlay actor gained durable publication authority")
    end
    local denied_owner = registry.overlay("foreign:owner")
    assert(not denied_owner, "unadmitted overlay owner opened")
    local live, open_error = registry.overlay(OWNER)
    assert(live, tostring(open_error))
    local outside = live:changes()
    assert(outside)
    local prepared_outside = outside:create({id = "foreign:entry", kind = "registry.entry", data = {value = "not-authorized"}})
    if prepared_outside then
        local escaped = outside:apply()
        assert(not escaped, "overlay owner escaped its entry scope")
    end
    local changes = live:changes()
    assert(changes)
    assert(changes:create({id = SUBJECT, kind = "registry.entry", data = {value = "first"}}))
    local created, create_error = changes:apply()
    assert(created, tostring(create_error))
    assert(created:id() == original, "overlay created durable history")
    local reviewed = registry.overlay(OWNER)
    local competing = registry.overlay(OWNER)
    assert(reviewed and competing)
    local stale = reviewed:changes()
    local fresh = competing:changes()
    assert(stale and fresh)
    assert(stale:update({id = SUBJECT, kind = "registry.entry", data = {value = "stale"}}))
    assert(fresh:update({id = SUBJECT, kind = "registry.entry", data = {value = "second"}}))
    assert(fresh:apply())
    local accepted, rejection = stale:apply()
    assert(not accepted and rejection, "stale owner generation accepted")
    assert(rejection:kind() == "Conflict", "stale generation did not return Conflict")
    local current = registry.snapshot()
    assert(current)
    local value = current:get(SUBJECT)
    assert(value and type(value.data) == "table" and value.data.value == "second", "rejected update changed effective entry")
    assert(current:version():id() == original, "overlay update created history")
    local foreign = registry.overlay("bee.governance_overlay_probe:other")
    assert(foreign)
    local collision = foreign:changes()
    assert(collision)
    assert(collision:create({id = SUBJECT, kind = "registry.entry", data = {value = "foreign"}}))
    local stolen = collision:apply()
    assert(not stolen, "foreign overlay stole owned entry")
    local cleanup = registry.overlay(OWNER)
    assert(cleanup)
    local removal = cleanup:changes()
    assert(removal)
    assert(removal:delete(cleanup:entries()))
    assert(removal:apply())
    local empty = registry.snapshot()
    assert(empty and not empty:get(SUBJECT), "explicit owner cleanup left entry visible")
    assert(empty:version():id() == original, "cleanup created history")
    logger:info("GOVERNANCE_OVERLAY_OWNER_PASS")
end
return {main = main}
